const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='sejong-erp-records-v4',REQUIRED=['project_name','ordering_organization','supplier_name','total_amount','supply_amount','vat_amount'];
let records=[],draft=null,group='project',readonly=false,dirty=false,route='#cases',leaveTarget=null,pendingImport=null,errors=[],toastTimer,saveTimer;
const copy=v=>JSON.parse(JSON.stringify(v));
const money=v=>numeric(v)===null?'—':numeric(v).toLocaleString('ko-KR')+'원';
const time=v=>new Date(v).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const number=r=>r.registrationId||'PUR-'+r.id.slice(0,8).toUpperCase();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function blank(){const now=new Date().toISOString();return {id:crypto.randomUUID(),title:'',type:'구매·계약',owner:'',memo:'',values:Object.fromEntries(SCHEMA.map(f=>[f.key,''])),method:'manual',fileName:'',status:'draft',createdAt:now,updatedAt:now,registrationId:null};}
function storeData(next=records,working=draft){try{localStorage.setItem(STORE,JSON.stringify({records:next,working:working?{record:working,dirty,readonly}:null}));return true;}catch{return false;}}
function markDirty(){dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(()=>storeData(),300);refreshSummary();}
function validate(r){const e=[];if(!r.title.trim())e.push({key:'title',message:'건명을 입력해 주세요.'});for(const f of SCHEMA){const v=String(r.values[f.key]??'').trim();if(REQUIRED.includes(f.key)&&!v)e.push({key:f.key,message:f.label+'을(를) 입력해 주세요.'});else if(v&&f.type==='number'&&(numeric(v)===null||numeric(v)<0))e.push({key:f.key,message:f.label+'에 0 이상의 숫자를 입력해 주세요.'});else if(v&&f.type==='date'){const d=new Date(v+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)e.push({key:f.key,message:'검수일을 올바른 날짜로 입력해 주세요.'});}}
 const a=numeric(r.values.total_amount),b=numeric(r.values.supply_amount),c=numeric(r.values.vat_amount);if([a,b,c].every(n=>n!==null)&&Math.abs(b+c-a)>.01)e.push({key:'total_amount',message:'공급가액 + 부가가치세가 총액과 일치해야 합니다.'});return e;}
function renderList(){const q=$('#listSearch').value.trim().toLowerCase(),status=$('#statusFilter').value,method=$('#methodFilter').value;const registered=records.filter(r=>r.status==='registered').length,excel=records.filter(r=>r.method==='excel').length;$('#navCount').textContent=records.length;$('#listCount').textContent=records.length;$('#metrics').innerHTML=[['전체 업무 건',records.length,'구매·계약 업무 현황','▤'],['작성 중',records.length-registered,'임시 저장된 업무 건','✎'],['등록 완료',registered,'저장된 구매·계약 정보','✓'],['Excel 입력',excel,'파일로 입력한 업무 건','▧']].map(([label,n,sub,icon],i)=>`<div class="case-metric"><span>${label}<i>${icon}</i></span><strong class="${i===2?'teal-value':''}">${n}<small>건</small></strong><p>${sub}</p></div>`).join('');const visible=records.filter(r=>(status==='all'||r.status===status)&&(method==='all'||r.method===method)&&(!q||[number(r),r.title,r.memo,r.values.project_name,r.values.supplier_name,r.owner].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));$('#listBody').innerHTML=visible.length?visible.map(r=>`<tr><td><small class="case-number">${esc(number(r))}</small><button class="case-title-link" data-record="${r.id}">${esc(r.title)}</button><p class="case-description-text">${esc(r.values.project_name||r.memo||'상세정보 작성 중')}</p></td><td><span class="case-type">${esc(r.values.supplier_name||'공급업체 미입력')}</span><div class="case-owner">${esc(r.owner||'담당자 미지정')}</div></td><td>${esc(money(r.values.total_amount))}</td><td><span class="method-pill ${r.method==='excel'?'excel':''}">${r.method==='excel'?'▧ Excel 입력':'✎ 직접 입력'}</span></td><td><span class="badge case-status ${r.status==='registered'?'done':'review'}">${r.status==='registered'?'✓ 등록 완료':'작성 중'}</span></td><td class="case-date">${esc(time(r.updatedAt))}</td><td><button class="case-open" data-record="${r.id}">${r.status==='registered'?'상세 보기':'이어서 작성'} ↗</button></td></tr>`).join(''):`<tr><td colspan="7" class="case-empty"><div>▤</div><h3>${records.length?'조건에 맞는 건이 없습니다.':'새 구매·계약 정보를 등록하세요.'}</h3><p>${records.length?'검색어와 필터를 변경해 주세요.':'신규 등록에서 직접 입력하거나 Excel 파일로 입력할 수 있습니다.'}</p></td></tr>`;$('#listResult').textContent=`전체 ${records.length}건 중 ${visible.length}건 표시`;$('#listBody').querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>navigate('#case/'+b.dataset.record));}
function renderTabs(){$('#fieldTabs').innerHTML=Object.entries(GROUPS).map(([key,label])=>`<button class="erp-tab ${group===key?'active':''}" data-group="${key}">${label}${errors.some(e=>SCHEMA.find(f=>f.key===e.key)?.group===key)?'<span class="tab-count">!</span>':''}</button>`).join('');$('#fieldTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{group=b.dataset.group;renderTabs();renderFields();});}
function renderFields(){const fields=SCHEMA.filter(f=>f.group===group);$('#groupTitle').textContent=GROUPS[group];$('#groupCount').textContent=fields.length+'개 항목';$('#fieldsForm').innerHTML=fields.map(f=>{const error=errors.find(e=>e.key===f.key);return `<div class="field ${f.full?'full':''} ${error?'invalid':''}"><label for="field-${f.key}">${esc(f.label)}${REQUIRED.includes(f.key)?'<span class="required-mark">*</span>':''}</label>${f.type==='textarea'?`<textarea id="field-${f.key}" data-field="${f.key}" ${readonly?'disabled':''}>${esc(draft.values[f.key])}</textarea>`:`<input id="field-${f.key}" data-field="${f.key}" type="${f.type==='date'?'date':'text'}" ${f.type==='number'?'inputmode="decimal"':''} value="${esc(draft.values[f.key])}" placeholder="${f.type==='number'?'0':esc(f.label)+' 입력'}" ${readonly?'disabled':''}>`}${error?`<p class="field-error">${esc(error.message)}</p>`:''}</div>`;}).join('');$('#fieldsForm').querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{draft.values[input.dataset.field]=input.value;errors=errors.filter(e=>e.key!==input.dataset.field);markDirty();});}
function refreshSummary(){if(!draft)return;const v=draft.values,filled=SCHEMA.filter(f=>String(v[f.key]).trim()).length,req=REQUIRED.filter(k=>String(v[k]).trim()).length;$('#summarySupply').textContent=money(v.supply_amount);$('#summaryVat').textContent=money(v.vat_amount);$('#summaryTotal').textContent=money(v.total_amount);const a=numeric(v.total_amount),b=numeric(v.supply_amount),c=numeric(v.vat_amount),complete=[a,b,c].every(n=>n!==null),ok=complete&&[a,b,c].every(n=>n>=0)&&Math.abs(b+c-a)<.01;$('#amountCheck').textContent=ok?'✓ 공급가액 + 부가가치세 = 총액':complete?'! 금액 합계가 일치하지 않습니다.':'정산금액을 입력해 주세요.';$('#amountCheck').className='amount-check '+(ok?'valid':complete?'invalid':'');$('#filledCount').textContent=filled+' / '+SCHEMA.length;$('#filledBar').style.width=filled/SCHEMA.length*100+'%';$('#requiredCount').textContent=`필수 상세항목 ${req} / ${REQUIRED.length} 입력`;$('#recordStatus').textContent=draft.status==='registered'?'등록 완료':'작성 중';$('#fileSource').textContent=draft.method==='excel'?'▧ 입력 파일: '+draft.fileName:'✎ 직접 입력';$('#methodBadge').textContent=draft.method==='excel'?'Excel 입력':'직접 입력';$('#saveStatus').textContent=readonly?'등록 완료':dirty?'저장되지 않은 변경':'작성 중';$('#saveInfo').textContent=readonly?number(draft):dirty?'작성 내용은 이 브라우저에 자동 보관됩니다.':'임시 저장 또는 등록하기를 선택하세요.';$('#dirtyDot').classList.toggle('ready',readonly);}
function renderEditor(){const saved=records.find(r=>r.id===draft.id);$('#recordTitle').value=draft.title;$('#recordType').value=draft.type;$('#recordOwner').value=draft.owner;$('#recordMemo').value=draft.memo;for(const id of ['recordTitle','recordType','recordOwner','recordMemo'])$('#'+id).disabled=readonly;$('#entryTitle').textContent=readonly?'구매·계약 상세 조회':saved?'구매·계약 정보 수정':'새 구매·계약 정보';$('#entryInfo').textContent=saved?`${number(draft)} · 최종 저장 ${time(saved.updatedAt)}`:'직접 작성하거나 Excel 파일로 입력할 수 있습니다.';$('#editRecord').hidden=!readonly;$('#manualEntry').hidden=readonly;$('#excelEntry').hidden=readonly;$('#draftSave').hidden=readonly;$('#registerSave').hidden=readonly;$('#draftSave').textContent=saved?.status==='registered'?'변경 저장':'임시 저장';$('#registerSave').textContent=saved?.status==='registered'?'수정 내용 저장 →':'등록하기 →';$('#savedBanner').hidden=!readonly;$('#savedBanner').textContent=readonly?`✓ 등록된 구매·계약 정보입니다. ${number(draft)} · 수정 버튼으로 내용을 변경할 수 있습니다.`:'';renderTabs();renderFields();refreshSummary();}
function applyRoute(target){clearTimeout(saveTimer);errors=[];route=target;if(target.startsWith('#case/')){const r=records.find(r=>r.id===target.slice(6));if(!r){toast('해당 건을 찾을 수 없습니다.');return applyRoute('#cases');}draft=copy(r);readonly=r.status==='registered';dirty=false;}else if(target==='#new'){draft=blank();readonly=false;dirty=false;}else{target='#cases';route=target;draft=null;readonly=false;dirty=false;}group='project';const list=target==='#cases';$('#listPage').hidden=!list;$('#editorPage').hidden=list;$('#backList').hidden=list;$('#newRecord').hidden=!list;$('#navList').classList.toggle('active',list||target.startsWith('#case/'));$('#navNew').classList.toggle('active',target==='#new');$('#pageTitle').textContent=list?'구매·계약 관리':target==='#new'?'구매·계약 신규 등록':readonly?'구매·계약 상세':'구매·계약 수정';$('#pageSubtitle').textContent=list?'구매부터 계약, 검수와 정산까지 업무 정보를 관리하세요.':'업무 정보를 직접 작성하거나 Excel 파일로 입력하세요.';$('#breadcrumb').textContent=list?'구매·계약 목록':target==='#new'?'신규 등록':'상세정보';renderList();if(!list)renderEditor();if(location.hash!==target)location.hash=target;storeData();window.scrollTo({top:0,behavior:'smooth'});}
function navigate(target){if(target===route)return;if(dirty&&draft){leaveTarget=target;$('#leaveDialog').showModal();return;}applyRoute(target);}
function saveRecord(status,after=null){clearTimeout(saveTimer);if(!draft)return false;const existing=records.find(r=>r.id===draft.id);if(existing?.status==='registered')status='registered';errors=status==='registered'?validate(draft):(!draft.title.trim()?[{key:'title',message:'임시 저장할 건명을 입력해 주세요.'}]:[]);if(errors.length){const first=errors[0];if(first.key==='title')$('#recordTitle').focus();else{group=SCHEMA.find(f=>f.key===first.key).group;renderTabs();renderFields();$('#field-'+first.key).focus();}toast(first.message);return false;}const saved=copy(draft);saved.title=saved.title.trim();saved.status=status;saved.updatedAt=new Date().toISOString();if(status==='registered'&&!saved.registrationId)saved.registrationId='ERP-'+new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('-','')+'-'+saved.id.slice(0,6).toUpperCase();const next=records.filter(r=>r.id!==saved.id);next.unshift(saved);const wasDirty=dirty;dirty=false;if(!storeData(next,saved)){dirty=wasDirty;toast('브라우저 저장 공간이 부족해 저장하지 못했습니다.');return false;}records=next;draft=saved;readonly=status==='registered';route='#case/'+saved.id;if(location.hash!==route)location.hash=route;applyRoute(after||route);toast(status==='registered'?'구매·계약 정보를 등록했습니다.':'작성 내용을 임시 저장했습니다.');return true;}
async function readExcel(file){if(!file)return;if(!/\.xlsx?$/i.test(file.name))return toast('XLSX 또는 XLS 파일을 선택해 주세요.');if(file.size>10*1024*1024)return toast('10MB 이하의 파일을 선택해 주세요.');try{const data=parseWorkbook(XLSX.read(await file.arrayBuffer(),{type:'array'}),file.name);pendingImport={data,values:Object.fromEntries(SCHEMA.map(f=>[f.key,initialValue(f,data.rows.find(r=>r.label===f.label))]))};$('#importInfo').textContent=file.name+' · '+data.rows.length+'개 항목 · 시트: '+data.sheet;$('#importBody').innerHTML=SCHEMA.map(f=>`<tr><td>${esc(f.label)}</td><td>${esc(f.type==='number'?money(pendingImport.values[f.key]):pendingImport.values[f.key]||'미입력')}</td></tr>`).join('');$('#importDialog').showModal();}catch(e){toast('Excel 입력 실패: '+e.message);}finally{$('#excelFile').value='';}}
function exportExcel(){if(!draft)return;const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet([[draft.title||'구매·계약 정보'],[],['항목','내용','확인'],...SCHEMA.map(f=>[f.label,f.type==='number'&&numeric(draft.values[f.key])!==null?numeric(draft.values[f.key]):draft.values[f.key],''])]);ws['!cols']=[{wch:26},{wch:90},{wch:14}];XLSX.utils.book_append_sheet(wb,ws,'최종확인');XLSX.writeFile(wb,(draft.title||'구매계약정보').replace(/[\\/:*?"<>|]/g,'_')+'.xlsx');}
function fromLegacy(c){const r=blank();r.id=c.id;r.title=c.title||c.data?.values?.project_name||'기존 업무 건';r.type=c.type||'구매·계약';r.owner=c.owner||'';r.memo=c.description||'';r.createdAt=c.createdAt||r.createdAt;r.updatedAt=c.updatedAt||r.createdAt;if(c.data?.values)for(const f of SCHEMA)r.values[f.key]=String(c.data.values[f.key]??'');r.method=c.data?.filename?'excel':'manual';r.fileName=c.data?.filename||'';r.status=c.data?.registered?'registered':'draft';r.registrationId=c.data?.registered||null;return r;}
function validRecord(r){return r&&r.id&&typeof r.title==='string'&&r.values&&SCHEMA.every(f=>Object.hasOwn(r.values,f.key));}
async function init(){let working;try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved&&Array.isArray(saved.records)){records=saved.records.filter(validRecord);working=saved.working;}else{const old=JSON.parse(localStorage.getItem('dox-erp-cases-v3'));if(Array.isArray(old?.cases))records=old.cases.map(fromLegacy);else{const v2=JSON.parse(localStorage.getItem('dox-erp-demo-v2'));if(v2?.state?.values)records=[fromLegacy({id:crypto.randomUUID(),title:v2.state.values.project_name,data:v2.state})];}}}catch{toast('이전 저장 데이터를 불러오지 못했습니다.');}if(!records.length){try{const response=await fetch('assets/bid-template.xlsx');if(response.ok){const d=parseWorkbook(XLSX.read(await response.arrayBuffer(),{type:'array'}),'DoxAI_Test01_Bid-Related Documents.xlsx');const r=blank();r.title='[샘플] 세종은행 서버 구매 계약';r.memo='구매·계약 정보 입력 예시입니다.';r.values=Object.fromEntries(SCHEMA.map(f=>[f.key,initialValue(f,d.rows.find(x=>x.label===f.label))]));r.method='excel';r.fileName=d.filename;records.push(r);}}catch{}}
 const target=location.hash||'#cases';applyRoute(target);if(working?.dirty&&validRecord(working.record)&&(target==='#new'||target==='#case/'+working.record.id)){draft=working.record;dirty=true;readonly=false;renderEditor();storeData();toast('작성 중이던 내용을 복원했습니다.');}}
$('#navList').onclick=()=>navigate('#cases');$('#backList').onclick=()=>navigate('#cases');$('#navNew').onclick=()=>navigate('#new');$('#newRecord').onclick=()=>navigate('#new');$('#listSearch').oninput=renderList;$('#statusFilter').onchange=renderList;$('#methodFilter').onchange=renderList;$('#fieldsForm').onsubmit=e=>e.preventDefault();for(const [id,key] of [['recordTitle','title'],['recordType','type'],['recordOwner','owner'],['recordMemo','memo']])$('#'+id).oninput=e=>{draft[key]=e.target.value;markDirty();};$('#draftSave').onclick=()=>saveRecord('draft');$('#registerSave').onclick=()=>saveRecord('registered');$('#editRecord').onclick=()=>{readonly=false;$('#pageTitle').textContent='구매·계약 수정';renderEditor();};$('#manualEntry').onclick=()=>{$('#field-'+SCHEMA.find(f=>f.group===group).key).focus();};$('#excelEntry').onclick=()=>$('#excelFile').click();$('#excelFile').onchange=e=>readExcel(e.target.files[0]);$('#closeImport').onclick=()=>$('#importDialog').close();$('#applyImport').onclick=()=>{if(!pendingImport||readonly)return;draft.values=pendingImport.values;draft.method='excel';draft.fileName=pendingImport.data.filename;if(!draft.title.trim())draft.title=draft.values.project_name;pendingImport=null;errors=[];$('#importDialog').close();markDirty();renderEditor();toast('Excel 내용을 입력란에 적용했습니다. 수정 후 저장하세요.');};$('#exportRecord').onclick=exportExcel;$('#downloadTemplate').onclick=()=>{const a=document.createElement('a');a.href='assets/bid-template.xlsx';a.download='ERP_구매계약_입력양식.xlsx';a.click();};$('#stayEdit').onclick=()=>{$('#leaveDialog').close();leaveTarget=null;};$('#discardEdit').onclick=()=>{const t=leaveTarget;dirty=false;$('#leaveDialog').close();applyRoute(t);};$('#saveAndLeave').onclick=()=>{if(saveRecord('draft',leaveTarget))$('#leaveDialog').close();};window.addEventListener('hashchange',()=>{const t=location.hash||'#cases';if(t!==route){if(dirty){history.replaceState(null,'',route);navigate(t);}else applyRoute(t);}});window.addEventListener('beforeunload',()=>{clearTimeout(saveTimer);storeData();});init();

